from html.parser import HTMLParser
from pathlib import Path

VOID = {'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr'}
OPTIONAL_END = {'p','li','tr','td','th','option','tbody','thead','dt','dd','caption'}

class Check(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.stack=[]; self.problems=[]; self.in_script=False; self.maxdepth=0
    def handle_starttag(self, tag, attrs):
        if tag in VOID: return
        self.stack.append((tag, self.getpos()))
        self.maxdepth=max(self.maxdepth,len(self.stack))
    def handle_endtag(self, tag):
        if tag in VOID: return
        if not self.stack:
            self.problems.append(('extra close', tag, self.getpos())); return
        if self.stack[-1][0]==tag:
            self.stack.pop(); return
        # find nearest
        for i in range(len(self.stack)-1,-1,-1):
            if self.stack[i][0]==tag:
                for t,pos in self.stack[i+1:]:
                    self.problems.append(('implicit close', t, pos, 'by', tag, self.getpos()))
                del self.stack[i:]
                return
        self.problems.append(('stray close', tag, self.getpos()))

h=Path('report.html').read_text(encoding='utf-8')
# 只检查模板结构部分，跳过内嵌脚本/样式内容体积
p=Check(); p.feed(h)
print("max depth:", p.maxdepth)
print("unclosed:", p.stack[:6])
for x in p.problems[:10]: print(x)
print("problems:", len(p.problems))
print("pre blocks:", h.count('<pre'), h.count('</pre>'))
print("data script close idx:", h.find('</script>'), "json tag idx:", h.find('id="app-data"'))
